SELECT eo.id AS opportunity_id, eo.symbol, eo.execution_source, eo.decision_code, eo.executed_at, s1.id AS one_id, s1.generated_at AS one_generated, s5.id AS five_id, s5.candle_open_time AS five_candle, s5.decision AS five_decision, s5.original_decision AS five_original, s5.confluence_status AS five_confluence, s5.final_entry_allowed AS five_final_allowed, s5.confidence_score AS five_confidence, pp.id AS paper_id, pp.status, pp.realized_pnl FROM crypto_ai.execution_opportunity eo JOIN crypto_ai.trade_signal s1 ON s1.id = eo.latest_signal_id AND s1.interval_code = '1m' LEFT JOIN crypto_ai.trade_signal s5 ON s5.id = (SELECT x.id FROM crypto_ai.trade_signal x WHERE x.symbol = s1.symbol AND x.interval_code = '5m' AND x.generated_at <= s1.generated_at ORDER BY x.generated_at DESC LIMIT 1) LEFT JOIN crypto_ai.paper_position pp ON pp.signal_id = s1.id WHERE eo.status = 'EXECUTED' ORDER BY eo.executed_at LIMIT 300